// Evolution manda TODO lo que pasa en la línea: acuses de entrega, ediciones,
// mensajes que el propio negocio escribió desde el celular. Aquí se decide, sin
// gastar un peso ni tocar la base, si esto merece atención.
const raw = $input.first().json;
const b   = raw.body || raw;
const d   = b.data || {};
const key = d.key || {};
const jid = String(key.remoteJid || '');
const msg = d.message || {};

const texto = String(
  msg.conversation ||
  (msg.extendedTextMessage && msg.extendedTextMessage.text) ||
  ''
).trim();

const telefono = jid.split('@')[0].replace(/\D/g, '');

// El modo prueba lo manda el panel del sandbox. Evolution nunca lo manda.
const test = b.test === true || d.test === true;

// Se guarda el motivo del descarte, no solo un booleano. Cuando alguien diga
// "el bot no me contestó", la respuesta está en el log de ejecuciones.
const razon =
  key.fromMe             ? 'mensaje propio del negocio' :
  jid.includes('@g.us')  ? 'viene de un grupo' :
  !texto                 ? 'sin texto (audio, imagen, sticker o estado)' :
  telefono.length < 8    ? 'remitente sin numero valido' :
  texto.length > 1500    ? 'mensaje absurdamente largo' : null;

return [{ json: {
  instance: b.instance || d.instance || '',
  telefono: telefono,
  texto: texto,
  wa_id: key.id || null,
  test: test,
  atender: razon === null,
  razon: razon
}}];

// ═══════════════════════════════════════════════════════════════════════════
// CUIDADO AL EDITAR ESTE NODO.
//
// El caché de Anthropic es un match de prefijo BYTE A BYTE. Si en el bloque
// "estable" de abajo se cuela algo que cambie entre un mensaje y el siguiente
// —la fecha, la hora, el nombre de quien escribe, un id— el caché deja de
// servir y la factura se multiplica por diez. Sin error, sin aviso, sin nada
// raro en los logs: solo llega la cuenta más alta a fin de mes.
//
// Lo que cambia va ABAJO, en los mensajes. Nunca aquí.
// ═══════════════════════════════════════════════════════════════════════════
const e    = $('Extraer mensaje').first().json;
const ctx  = $input.first().json.ctx;
const cfg  = ctx.config || {};
const id   = cfg.identidad || {};
const lim  = cfg.limites || {};
const cap  = cfg.captura || {};
const enr  = cfg.enrutamiento || {};

const negocio = id.negocio || ctx.empresa;

const partes = [];
partes.push('Eres el asistente de ' + negocio + ' y atiendes por WhatsApp.');

partes.push('\n## Como hablas');
partes.push(id.tono || 'Cercano y directo, tuteando, en espanol de Colombia.');
partes.push(
  'Respondes CORTO: esto es WhatsApp, no un correo. Dos o tres frases. Sin ' +
  'listas largas, sin negritas, sin titulos. Si te preguntan varias cosas, ' +
  'contestas todas pero breve.'
);

partes.push('\n## Lo que NO haces');
partes.push('- No inventas NADA. Si algo no esta escrito mas abajo, no existe.');
partes.push('- No prometes precios, plazos, cupos ni descuentos que no esten escritos.');
partes.push('- Si no sabes algo, lo dices sin rodeos y ofreces pasarlo a una persona.');
if (Array.isArray(lim.nunca)) {
  for (const r of lim.nunca) partes.push('- ' + r);
}

// Los campos a capturar. Sin ellos el agente responde bien pero no deja nada
// util: el negocio se queda con una conversacion amable y ningun dato.
const campos = Array.isArray(cap.campos) ? cap.campos : [];
if (campos.length) {
  partes.push('\n## Lo que tienes que averiguar');
  for (const c of campos) {
    // La CLAVE va explicita. Sin ella el modelo entiende que tiene que
    // averiguar el nombre —y lo averigua— pero lo devuelve bajo la etiqueta
    // que se le ocurra, y el dato se pierde al guardarlo. Probado: dijo
    // 'soy Marcela', el agente la llamo Marcela, y el contacto quedo sin nombre.
    partes.push('- `' + c.clave + '`: ' + (c.etiqueta || c.clave) + (c.obligatorio ? ' (importante)' : ''));
  }
  partes.push(
    'Cuando alguno de esos datos quede CLARO, devuelvelo en `datos` usando ' +
    'EXACTAMENTE la clave entre comillas de la izquierda. No inventes otras claves.'
  );
  partes.push(
    'No los pides todos de una: eso espanta. Los vas pidiendo de a uno, cuando ' +
    'venga al caso en la conversacion.'
  );
}

const reglas = Array.isArray(enr.reglas) ? enr.reglas : [];
if (reglas.length) {
  partes.push('\n## Cuando dejar de responder tu');
  for (const r of reglas) {
    partes.push('- Si ' + r.si + ' -> ' + r.accion + (r.destino ? ' (' + r.destino + ')' : ''));
  }
}
if (Array.isArray(lim.escalar_si)) {
  for (const r of lim.escalar_si) partes.push('- Si ' + r + ' -> escalar');
}

partes.push('\n## Lo que sabes de ' + negocio);
partes.push(cfg.conocimiento && cfg.conocimiento.trim()
  ? cfg.conocimiento
  : '(Todavia no hay informacion cargada. No inventes: di que lo confirmas y escala.)');

const sistema = partes.join('\n');

// La herramienta obliga a que la respuesta venga estructurada. Pedirle el JSON
// "por favor" en el prompt funciona el 95% de las veces, y el 5% restante son
// mensajes rotos que le llegan a un cliente real.
const herramienta = {
  name: 'responder',
  description: 'Responde al cliente por WhatsApp. Usala siempre, una sola vez por mensaje.',
  input_schema: {
    type: 'object',
    properties: {
      respuesta: { type: 'string', description: 'Lo que se le escribe al cliente. Dos o tres frases.' },
      datos: {
        type: 'object',
        description: 'Datos del cliente que quedaron CLAROS en este mensaje. Vacio si no quedo claro ninguno. Nunca adivinar.',
        additionalProperties: { type: 'string' }
      },
      accion: {
        type: 'string',
        enum: ['responder', 'escalar', 'enviar_link', 'agendar'],
        description: 'responder = ya quedo resuelto. escalar = necesita una persona. enviar_link = mandarlo a una pagina. agendar = quiere una cita.'
      },
      destino: { type: 'string', description: 'A donde: la url del link, o a que grupo escalar. Vacio si accion es responder.' },
      motivo:  { type: 'string', description: 'En una linea, por que elegiste esa accion. Para el log, el cliente no lo ve.' },
      // El cliente NO ve esto. Sirve para dos cosas: obliga a mirar de donde
      // sale cada dato antes de decirlo, y permite comprobar despues que el
      // titulo citado exista de verdad en el documento. Si se lo inventa,
      // queda la huella.
      fuente:  { type: 'string', description: 'El titulo exacto de la seccion del conocimiento de donde sacaste el dato principal. Vacio si la respuesta no usa ningun dato del documento, como un saludo. NUNCA inventes un titulo.' }
    },
    required: ['respuesta', 'accion']
  }
};

// El historial viene viejo->nuevo. Se colapsan turnos seguidos del mismo lado:
// la API exige que user y assistant se alternen.
const mensajes = [];
for (const h of (ctx.historial || [])) {
  const rol = h.dir === 'in' ? 'user' : 'assistant';
  if (mensajes.length && mensajes[mensajes.length - 1].role === rol) {
    mensajes[mensajes.length - 1].content += '\n' + h.texto;
  } else {
    mensajes.push({ role: rol, content: h.texto });
  }
}

// Lo que cambia en cada mensaje va aqui abajo, DESPUES del prefijo cacheado.
// El nombre de quien escribe incluido: meterlo en el sistema le daria a cada
// cliente su propio prefijo y no se cachearia nunca nada.
const quien = ctx.contacto && ctx.contacto.nombre;
const ultimo = (quien ? '[Escribe ' + quien + ']\n' : '') + e.texto;
if (mensajes.length && mensajes[mensajes.length - 1].role === 'user') {
  mensajes[mensajes.length - 1].content += '\n' + ultimo;
} else {
  mensajes.push({ role: 'user', content: ultimo });
}

const modelo = $env.TOQUE_MODELO_AGENTE || 'claude-haiku-4-5-20251001';

return [{ json: {
  modelo: modelo,
  // Haiku 4.5 solo cachea prefijos de 4096 tokens o mas. Por debajo de eso el
  // marcador no da error: simplemente no cachea. Se estima a 4 caracteres por
  // token para poder avisarlo en el log en vez de descubrirlo en la factura.
  prefijo_tokens_aprox: Math.round(sistema.length / 4),
  cachea: Math.round(sistema.length / 4) >= 4096,
  cuerpo: {
    model: modelo,
    max_tokens: 700,
    // Por defecto la API viene en 1. Para un asistente que tiene que repetir
    // precios y horarios sin adornar, la variabilidad no aporta nada: solo
    // hace que la misma pregunta se conteste distinto dos veces. En 0 las
    // pruebas tambien se vuelven reproducibles.
    temperature: 0,
    system: [{
      type: 'text',
      text: sistema,
      cache_control: { type: 'ephemeral', ttl: '1h' }
    }],
    tools: [herramienta],
    tool_choice: { type: 'tool', name: 'responder' },
    messages: mensajes
  }
}}];

const r = $input.first().json;
const e = $('Extraer mensaje').first().json;
const a = $('Armar el prompt').first().json;

const bloque = (r.content || []).find(c => c.type === 'tool_use');
if (!bloque) {
  // Con tool_choice forzado esto no deberia pasar nunca. Si pasa, se prefiere
  // el silencio a mandarle al cliente un mensaje roto o vacio.
  throw new Error('Claude no uso la herramienta. stop_reason=' + r.stop_reason);
}

const out = bloque.input || {};
const u   = r.usage || {};

// Si el prefijo era cacheable y aun asi no hubo lectura, algo lo esta
// invalidando. Queda escrito en el log: es la unica forma de enterarse.
const leido = u.cache_read_input_tokens || 0;
const alerta = (a.cachea && leido === 0) ? 'CACHE NO LEIDO: revisar que nada cambie en el bloque estable' : null;

return [{ json: {
  respuesta: String(out.respuesta || '').trim(),
  datos:     out.datos || {},
  accion:    out.accion || 'responder',
  destino:   out.destino || '',
  motivo:    out.motivo || '',
  fuente:    out.fuente || '',

  // Un solo jsonb para la funcion de registro: sin comas que contar.
  registro: {
    instance:    e.instance,
    telefono:    e.telefono,
    entrante:    e.texto,
    respuesta:   String(out.respuesta || '').trim(),
    datos:       out.datos || {},
    wa_id:       e.wa_id,
    model:       a.modelo,
    input:       u.input_tokens || 0,
    output:      u.output_tokens || 0,
    cache_read:  leido,
    cache_write: u.cache_creation_input_tokens || 0,
    test:        e.test
  },

  diagnostico: {
    prefijo_tokens: a.prefijo_tokens_aprox,
    cachea: a.cachea,
    cache_read: leido,
    cache_write: u.cache_creation_input_tokens || 0,
    alerta: alerta
  }
}}];
